ensemble_members = {
    "dense": {"weight": 0.5, "results": ["c1", "c3", "c2"]},
    "sparse": {"weight": 0.3, "results": ["c3", "c4", "c1"]},
    "metadata": {"weight": 0.2, "results": ["c1", "c2"]},
}

def weighted_reciprocal_rank_fusion(members, k=60):
    # Combine member scores using their configured weights
    scores = {}
    for member_name, member_data in members.items():
        for rank, chunk_id in enumerate(member_data["results"], start=1):
            contribution = member_data["weight"] / (k + rank)
            scores[chunk_id] = scores.get(chunk_id, 0) + contribution
    return sorted(scores.items(), key=lambda x: -x[1])

print("Ensemble members:")
for name, data in ensemble_members.items():
    print(f"  {name}: weight={data['weight']}, results={data['results']}")

merged = weighted_reciprocal_rank_fusion(ensemble_members)
print(f"\nFinal weighted merged results:")
for chunk_id, score in merged:
    print(f"  {chunk_id}: {score:.5f}")
